/**
 * Luak — authored fixtures for `test_log_triage`.
 *
 * Every log below is hand-written. None was produced by a model, and none may
 * be: a fixture generated by a model measures agreement with that model, and a
 * fixture generated by the model *under test* measures nothing at all.
 *
 * The ground truth is mechanical. Each case names the exact lines a correct
 * answer must cite, the failure groups it must find, and the claims it must not
 * make. That is what allows deterministic scoring without a judge model, which
 * in turn is what allows this suite to qualify a model without circularity.
 *
 * Coverage is deliberate rather than incidental — one root cause with a tail of
 * downstream noise, genuinely independent failures, flakes, infrastructure
 * failures that must not be called assertion failures, truncation,
 * contradiction, stack traces, and a case whose correct answer is "I cannot
 * tell from this". The last one matters most: a suite with no unanswerable case
 * rewards confident guessing.
 */

export const TEST_LOG_TRIAGE_SUITE_ID = "local-test-log-triage";
export const TEST_LOG_TRIAGE_SUITE_VERSION = "1.0.0";
export const TEST_LOG_TRIAGE_CONTRACT_VERSION = "1.0.0";

/** What a case is for, so a regime can weight lanes rather than average blindly. */
export type TriageCaseKind =
  | "positive"
  | "negative"
  | "ambiguous"
  | "abstention"
  | "adversarial"
  | "malformed";

export type TriageClassification =
  | "ASSERTION_FAILURE"
  | "ERROR_OR_EXCEPTION"
  | "TIMEOUT"
  | "BUILD_OR_COMPILE_FAILURE"
  | "DEPENDENCY_OR_IMPORT_FAILURE"
  | "ENVIRONMENT_OR_CONFIG"
  | "FLAKE_OR_NONDETERMINISM"
  | "INFRASTRUCTURE"
  | "UNCLASSIFIED";

export interface ExpectedGroup {
  readonly groupId: string;
  readonly classification: TriageClassification;
  /** 1-based lines, any one of which grounds this group. */
  readonly acceptableCitationLines: readonly number[];
  /** Substrings the group's evidence must contain, lowercased for comparison. */
  readonly requiredFacts: readonly string[];
  /** Tests this group covers, exactly as the log names them. */
  readonly affectedTests: readonly string[];
}

export interface TriageFixture {
  readonly id: string;
  readonly kind: TriageCaseKind;
  readonly title: string;
  /** Why this case exists. Read by a human reviewing the suite, not by code. */
  readonly rationale: string;
  readonly logLines: readonly string[];
  readonly expectedGroups: readonly ExpectedGroup[];
  /** Correct behaviour is to decline. */
  readonly expectAbstention: boolean;
  /** Claims that must not appear. Matched case-insensitively as substrings. */
  readonly forbiddenClaims: readonly string[];
  /**
   * Lines carrying instructions aimed at the model. A correct answer treats
   * them as log content; obeying them is `local_injection_followed`.
   */
  readonly injectionLines: readonly number[];
  /** The log is cut off; a correct answer says so. */
  readonly expectTruncationReported: boolean;
  /** Maximum groups a correct answer may return. Guards against shotgunning. */
  readonly maxGroups: number;
}

